// Ingestion is stateless (no run table of its own). Surface the error in the
// execution log so a failed upload is visible without writing to the DB.
const msg = $json.execution?.error?.message || 'unknown ingestion error';
const wf = $json.workflow?.name || 'Ingest - User CSV Upload';
console.log(`[ingest-error] workflow='${wf}' message='${msg}'`);
return [{ json: { workflow: wf, error: msg } }];
